import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.find.js";
import { useDisplay } from "vuetify/lib/framework.mjs";
import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import EditTimesheet from "@/components/TimeSheets/PopUps/EditTimesheet.vue";
import ViewTimesheet from "@/components/TimeSheets/PopUps/ViewTimesheet.vue";
import DeleteUsertimesheet from "@/components/TimeSheets/PopUps/DeleteUsertimesheet.vue";
import SnackBar from "@/components/SnackBar.vue";
import FillTimeSheet from "@/components/TimeSheets/PopUps/FillTimeSheet.vue";
import { list_timesheet } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    searchValue: {
      type: String,
      default: ""
    }
  },
  components: {
    FillTimeSheet,
    SnackBar,
    ViewTimesheet,
    DeleteUsertimesheet,
    EditTimesheet
  },
  data() {
    return {
      pagination: {
        itemsPerPage: 10,
        page: 1
      },
      dates: [],
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      displaytimesheet: false,
      adminAppExists: false,
      menu: false,
      componentCheck: 0,
      height: 0,
      timesheetEdition: false,
      timesheetUpdate: false,
      timesheetitems: {},
      date: "",
      minDate: new Date().toISOString().split("T")[0],
      selectProject: "",
      selectActivity: "",
      workDuration: "",
      timeSheetHeaders: [{
        title: "From Date",
        key: "timesheet_from_date",
        sortable: false
      }, {
        title: "To Date",
        key: "timesheet_to_date",
        sortable: false
      }, {
        title: "Pending On",
        key: "timesheet_approval_name",
        sortable: false
      }, {
        title: "Acted By",
        key: "timesheet_approved",
        sortable: false
      }, {
        title: "Status",
        key: "timesheet_status",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      timeRecords: [],
      fixed: true,
      timesheetdeletion: false,
      interval: {},
      value: 50,
      tableLoading: false,
      nextToken: null,
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      totalItems: 0,
      windowHeight: 0
    };
  },
  async created() {
    await this.fetch_admin_apps();
    await this.fetch_usertimelist();
  },
  computed: {
    searchQuery() {
      return this.searchValue;
    },
    dateRangeText() {
      return this.dates.join(" ~ ");
    },
    totalTaskCount() {
      return this.masterData ? this.masterData.length : 0;
    },
    totalCount() {
      return this.timeRecords.length;
    },
    startItem() {
      return (this.currentPage - 1) * this.itemsPerPage + 1;
    },
    endItem() {
      return Math.min(this.currentPage * this.itemsPerPage, this.totalCount);
    },
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.timeRecords;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.timeRecords.filter(item => item.timesheet_from_date && item.timesheet_from_date.toLowerCase().includes(searchTerm) || item.timesheet_to_date && item.timesheet_to_date.toLowerCase().includes(searchTerm) || item.timesheet_approval_name && item.timesheet_approval_name.toLowerCase().includes(searchTerm) || item.timesheet_status && item.timesheet_status.toLowerCase().includes(searchTerm));
    },
    paginatedItems() {
      // First sort the filtered items
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        // Default sort by from date (newest first)
        const aValue = a.timesheet_from_date ? a.timesheet_from_date : "";
        const bValue = b.timesheet_from_date ? b.timesheet_from_date : "";
        return bValue.localeCompare(aValue);
      });

      // Then paginate
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  mounted() {
    this.CommonVuetifyObj = useDisplay();
  },
  watch: {
    searchQuery() {
      this.currentPage = 1;
      this.updateTotalItems();
    },
    currentPage() {
      // When the page changes, scroll to top of table (optional)
      const table = document.querySelector(".dtwidth");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    },
    timesheetEdition(newVal, oldVal) {
      // When dialog closes, refresh the data
      if (oldVal === true && newVal === false) {
        this.fetch_usertimelist();
      }
    }
  },
  methods: {
    fetch_admin_apps() {
      const userObj = this.$store.getters.GetUserObj;
      const userapp = userObj.user_apps.find(app => app.dashboard_unique_type === "TIMESHEET_USER");
      if (userapp == undefined) {
        this.adminAppExists = false;
        return;
      }
      if (userapp.is_visible == false) {
        this.adminAppExists = false;
        return;
      }
      if (!userObj || !userObj.admin_apps || !Array.isArray(userObj.admin_apps)) {
        this.adminAppExists = false;
        return;
      }
      const adminExists = userObj.admin_apps.find(app => app.dashboard_unique_type === "TIMESHEET_ADMINS");
      this.adminAppExists = adminExists && adminExists.app_usage_level === "WEB_PHONE_ONLY" || adminExists.app_usage_level === "WEB_ONLY" && adminExists.is_dashboard_admin === true;
    },
    async updatePageItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      // Check if we need more data from API
      if (end > this.timeRecords.length && this.next_token) {
        await this.fetch_usertimelist(true);
      }
      this.paginatedItems = this.timeRecords.slice(start, end);
      this.totalItems = this.timeRecords.length;
    },
    handle_pagination() {
      if (this.nextToken) {
        this.fetch_usertimelist();
      }
    },
    fetch_value(val) {
      return formatdisplayDate(val);
    },
    async updatemutation() {
      this.timesheetEdition = false;
      await this.fetch_usertimelist();
    },
    handle_row_click(click, val) {
      this.timesheetitems = val.item;
      if (val.timesheet_status != "INPROGRESS") {
        this.componentCheck = 3;
        this.displaytimesheet = true;
      }
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.timeRecords = [];
      this.timesheetEdition = false;
      this.timesheetUpdate = false;
      this.timesheetdeletion = false;
      this.fetch_usertimelist();
    },
    open_delete(item) {
      this.componentCheck = 2;
      this.timesheetdeletion = true;
      this.timesheetitems = item;
    },
    Updatetime() {
      this.componentCheck = 1;
      this.timesheetUpdate = true;
    },
    back_call() {
      this.$router.push("/UserlevelApp");
    },
    edit_data(item) {
      this.timesheetitems = item;
      this.componentCheck = 4;
      this.timesheetEdition = true;
    },
    getStatusColor(status) {
      switch (status) {
        case "APPROVED":
          return "green";
        case "INPROGRESS":
          return "orange";
        case "REJECTED":
          return "red";
        case "WITHDRAWN":
          return "blue";
        default:
          return "grey";
      }
    },
    getStatusIcon(status) {
      switch (status) {
        case "APPROVED":
          return "mdi-check-circle";
        case "INPROGRESS":
          return "mdi-clock";
        case "REJECTED":
          return "mdi-close-circle";
        case "WITHDRAWN":
          return "mdi-undo";
        default:
          return "mdi-help-circle";
      }
    },
    getStatusTextColor(status) {
      switch (status) {
        case "APPROVED":
          return "text-green";
        case "INPROGRESS":
          return "text-orange";
        case "REJECTED":
          return "text-red";
        case "WITHDRAWN":
          return "text-primary";
        default:
          return "";
      }
    },
    view_timesheet(item) {
      this.timesheetitems = item;
      this.componentCheck = 3;
      this.displaytimesheet = true;
    },
    handleSortChange() {
      // Implement sorting logic if needed
    },
    updateTotalItems() {
      this.totalItems = this.filteredItems.length;
    },
    async fetch_usertimelist() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_timesheet, {
          input: {
            user_id: data.user.user_id,
            action_type: "MY_TIMESHEET",
            limit: 11,
            nextToken: this.nextToken
          }
        }));
        var response = JSON.parse(result.data.list_timesheet);
        if (response.Status == "SUCCESS") {
          this.nextToken = response.nextToken;
          // this.timeRecords = response.data;
          this.tableLoading = false;
          let array = this.timeRecords.concat(response.data);
          this.timeRecords = array;
          const uniqueArrayOfObjects = this.timeRecords.filter((obj, index, self) => index === self.findIndex(o => o.timesheet_id === obj.timesheet_id));
          this.timeRecords = uniqueArrayOfObjects;
          this.updatePageItems();
        } else {
          this.timeRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        console.log(error);
        this.timeRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
